package com.example;import org.springframework.stereotype.Service;import java.util.*;@Service public class EmployeeService {private final EmployeeRepository repo;public EmployeeService(EmployeeRepository repo){this.repo=repo;}public void addEmployee(Employee e){repo.save(e);}public List<Employee> listEmployees(){return repo.findAll();}public double totalSalary(){return repo.findAll().stream().mapToDouble(Employee::getSalary).sum();}}
